// --- CÓDIGO DEFINITIVO PARA PROCESSAR O CARRINHO E EXTRAIR ITENS ---

console.log("--- INICIANDO PROCESSAMENTO DO CARRINHO ---");

const sessao = $items('busca_carrinho_atual')[0].json;
const carrinho = sessao.carrinho_json;
const mapa = sessao.mapa_id_json;

if (!carrinho || !Array.isArray(carrinho) || carrinho.length === 0) {
  console.log("Carrinho está vazio ou inválido.");
  return [];
}

let mapaObjeto = {};
if (typeof mapa === 'string') {
  try {
    mapaObjeto = JSON.parse(mapa);
  } catch(e) {
    mapaObjeto = {};
  }
} else if (typeof mapa === 'object' && mapa !== null) {
  mapaObjeto = mapa;
}

let totalGeral = 0;
let carrinhoTexto = "";

// mapa reverso
const mapaReverso = {};
for (const indice in mapaObjeto) {
  const idDoItem = mapaObjeto[indice].id;
  mapaReverso[idDoItem] = indice;
}

// LOOP PRINCIPAL
for (const item of carrinho) {

  const subtotal = (item.qtd || 0) * (item.precoUnitario || 0);
  const unitario = item.precoUnitario || 0;
  totalGeral += subtotal;

  const precoUnitarioFormatado = unitario.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  const subtotalFormatado = subtotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const indice = item.indice || "?"; 

  // CABEÇALHO ITEM
  carrinhoTexto += `*${indice})* `;
  if (item.nome.toLowerCase().includes('combo')) {
    carrinhoTexto += `📦 ${item.nome.trim()}\n\n`;
  } else {
    carrinhoTexto += `🍫 ${item.nome.trim()}\n\n`;
  }

  carrinhoTexto += `*Quantidade:* ${item.qtd}\n`;
  carrinhoTexto += `*Preço:* ${precoUnitarioFormatado} *(${subtotalFormatado})*\n`;

  // 👉 NOVO TRECHO — ITENS INTERNOS DO COMBO
  if (item.itens_internos && item.itens_internos.length > 0) {
    carrinhoTexto += `*Itens do Combo:*\n`;

    item.itens_internos.forEach(subItem => {
      carrinhoTexto += `${subItem.qtd}x ${subItem.nome}\n`;
    });

    carrinhoTexto += `\n\n`;
  }

  carrinhoTexto += `----------------------------------------------------------\n\n`;
}

// MENSAGEM FINAL
let mensagemFinal = `*🛍️→ PEDIDO:*\n\n`;
mensagemFinal += carrinhoTexto;
mensagemFinal += `*🪙→ VALOR PEDIDO:*\n`;
mensagemFinal += `*${totalGeral.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace('.', ',')}*\n\n`;
mensagemFinal += `*💳→ FORMAS DE PAGAMENTO:*\n`;
mensagemFinal += `(PIX, Cartão de Crédito\n`;
mensagemFinal += `e Saldo Mercado Pago)\n\u200B`;

let salva_carrinho = `*🛍️→ PEDIDO:*\n\n`;
salva_carrinho += carrinhoTexto;
salva_carrinho += `*🪙→ VALOR PEDIDO:*\n`;
salva_carrinho += `*${totalGeral.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace('.', ',')}*\n\n`;
salva_carrinho += `*💳→ FORMAS DE PAGAMENTO:*\n`;
salva_carrinho += `(PIX, Cartão de Crédito\n`;
salva_carrinho += `e Saldo Mercado Pago)\n`;

const resultadoFinal = {
  Jid: sessao.jid,
  telefone_real: sessao.telefone_real,
  primeiro_nome: sessao.primeiro_nome,
  print_carrinho: salva_carrinho,
  mensagemResposta: mensagemFinal,
  valor_pedido: totalGeral.toFixed(2)
};

console.log("--- PROCESSAMENTO CONCLUÍDO. SAÍDA GERADA. ---");
return [{ json: resultadoFinal }];

