verifica_endereco += `*📍→ CEP:*\n\n`;
verifica_endereco += `${endereco.CEP.slice(0,5) + '-' + endereco.CEP.slice(5)}\n\n`;
if (!endereco.complemento) {
verifica_endereco += `\u200B`
} else {
